package com.company.platform.inventory.domain;
import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
public record PackingTask(UUID id,UUID tenantId,UUID fulfillmentId,String packageNumber,BigDecimal packageWeight,BigDecimal packageVolume,PackingStatus status,Instant packedAt){public PackingTask{if(tenantId==null||fulfillmentId==null||packageNumber==null||packageWeight==null||packageVolume==null||packageWeight.signum()<=0||packageVolume.signum()<=0)throw new IllegalArgumentException("invalid packing task");}public PackingTask complete(){if(status!=PackingStatus.IN_PROGRESS)throw new IllegalStateException("packing task is not active");return new PackingTask(id,tenantId,fulfillmentId,packageNumber,packageWeight,packageVolume,PackingStatus.COMPLETED,Instant.now());}}
